// Renders the demo pages into public/demo/ so the tag always carries the website id the seed
// registers and the tracker path and integrity from public/s/manifest.json.
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';

const PUBLIC_ROOT = path.resolve(import.meta.dirname, '..', 'public');

function renderPage({ title, linkHref, linkText, websiteId, gatewayOrigin, manifest }) {
  return `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <title>Usage Signals demo: ${title}</title>
    <!-- Generated by scripts/demo-pages.mjs. Pinned Umami tracker served by the gateway. -->
    <script
      defer
      src="${gatewayOrigin}${manifest.path}"
      integrity="${manifest.integrity}"
      crossorigin="anonymous"
      data-host-url="${gatewayOrigin}"
      data-website-id="${websiteId}"
    ></script>
  </head>
  <body>
    <h1>Usage Signals demo: ${title}</h1>
    <p>Demo tenant site for the Usage Signals proof of concept.</p>
    <nav>
      <a href="${linkHref}">${linkText}</a>
      <a href="https://stellar.org/">Stellar</a>
    </nav>
  </body>
</html>
`;
}

/** Returns the demo pages as `{ fileName: html }`. */
export function renderDemoPages(tag) {
  return {
    'index.html': renderPage({ ...tag, title: 'Home', linkHref: 'about.html', linkText: 'About' }),
    'about.html': renderPage({ ...tag, title: 'About', linkHref: './', linkText: 'Home' }),
  };
}

export async function writeDemoPages(demo) {
  const manifest = JSON.parse(await readFile(path.join(PUBLIC_ROOT, 's', 'manifest.json'), 'utf8'));
  const directory = path.join(PUBLIC_ROOT, 'demo');
  await mkdir(directory, { recursive: true });
  for (const [fileName, html] of Object.entries(renderDemoPages({ ...demo, manifest }))) {
    await writeFile(path.join(directory, fileName), html);
  }
}
